#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using Builda;
using UnityEngine;

namespace MVZ2.Saves
{
    /// <summary>
    /// 云端存档同步（基于 Builda 的 privateKV）。
    ///
    /// 设计要点：
    /// - 键名固定，不依赖「列出所有 key」的接口（privateKV 没有 list）：
    ///     mvz2.users                     → userdata/users.dat
    ///     mvz2.u{userIndex}.{modNs}      → userdata/{user}/{mod}/user.dat
    /// - 每个存档值可能超过 privateKV 的 32KB 限制，所以分块存储在 `{key}.{i}`：
    ///     chunk 0 头部 = [u8 版本][i32 分块总数][i64 数据总长][i64 mtime]
    ///   读取时先拿 chunk 0 解析头部，再批量拉取剩余分块。
    /// - 冲突解决：比较存档的 mtime（最后写入时间），新的覆盖旧的。
    /// - 本地存档永远是权威副本：先用本地，云端只做「有更新则覆盖本地」和「本地有更新则上传」。
    /// - 任何一步失败都只打日志、不抛异常，绝不阻塞游戏加载。
    /// </summary>
    public enum PullResult
    {
        /// <summary>云端没有这个 key。</summary>
        Missing,
        /// <summary>云端有，但不需要覆盖本地（本地更新或数据异常）。</summary>
        Skipped,
        /// <summary>已用云端数据覆盖本地。</summary>
        Restored,
    }

    public static class CloudSaveManager
    {
        public const byte FORMAT_VERSION = 1;
        /// <summary>单块原始数据大小。平台限制是「解码后 ≤32KB」，30KB 留了余量。</summary>
        private const int CHUNK_SIZE = 30 * 1024;
        /// <summary>
        /// 分块数上限。单文件最大约 1.2MB；同时要兼顾 privateKV「每玩家每游戏 100 个活 key」，
        /// 目前实际用到的 key 很少（users/options/packs/langpacks + 每用户每mod 一个），余量充足。
        /// </summary>
        private const int MAX_CHUNKS = 40;
        private const string KEY_PREFIX = "mvz2_";
        /// <summary>探测用户时最多向后看多少个 userIndex。</summary>
        private const int MAX_PROBE_USERS = 8;
        private const string USERS_KEY = KEY_PREFIX + "users";
        private const string OPTIONS_KEY = KEY_PREFIX + "options";
        private const string PACKS_KEY = KEY_PREFIX + "packs";
        private const string LANGPACKS_KEY = KEY_PREFIX + "langpacks";
        /// <summary>关卡进行中存档（.lvl）的文件名也存一份，还原时才知道该写回哪个文件名。</summary>
        private const string LEVEL_NAME_PREFIX = KEY_PREFIX + "lvlname_";
        private const string LEVEL_PREFIX = KEY_PREFIX + "lvl_";
        private const string OPTIONS_FILE = "options.json";
        private const string PACKS_FILE = "resource_packs.json";
        private const string LANGPACKS_FILE = "language_packs.json";

        /// <summary>本次会话内已经检查过云端的文件路径，避免重复请求。</summary>
        private static readonly HashSet<string> pulledPaths = new HashSet<string>();
        private static bool pullFinished;
        /// <summary>超时中止后不再写本地文件，避免和正常的存档加载撞车。</summary>
        private static bool aborted;
        private static bool pushing;

        /// <summary>当前平台是否可能支持云端存档（非 WebGL 直接跳过）。</summary>
        public static bool Supported => Application.platform == RuntimePlatform.WebGLPlayer;

        #region 启动时拉取
        /// <summary>
        /// 在 SaveManager.Load() 之前调用：把云端较新的存档拉到本地。
        /// 失败或超时都不影响后续加载（本地存档仍然可用）。
        /// </summary>
        public static async Task PullAllAsync(string saveRoot, IReadOnlyList<string> modNamespaces)
        {
            if (!Supported || pullFinished)
                return;
            pullFinished = true;

            try
            {
                // 平台 privateKV 是宿主 API，正常应该很快返回；但审核/异常环境里绝不能让它拖住启动，
                // 所以整体设置一个帧级硬超时（约 12 秒），超时后直接继续用本地存档。
                var pullTask = DoPullAsync(saveRoot, modNamespaces);
                var timeoutTask = FrameTimeout.AfterFrames(720);
                var finished = await Task.WhenAny(pullTask, timeoutTask);
                if (finished != pullTask)
                {
                    aborted = true;
                    Debug.LogWarning("[CloudSave] 云端存档拉取超时，本次直接使用本地存档");
                    return;
                }
                Debug.Log("[CloudSave] 云端存档拉取完成");
            }
            catch (Exception e)
            {
                Debug.LogWarning($"[CloudSave] 拉取云端存档失败（忽略，继续用本地存档）：{e}");
            }
        }
        private static async Task DoPullAsync(string saveRoot, IReadOnlyList<string> modNamespaces)
        {
            {
                // 用户列表本身也同步。
                // 注意：必须用 remoteNewerOnly=true —— 本地文件不存在时照样会还原（换设备场景），
                // 但本地较新时绝不能被云端旧副本覆盖，否则一次上传失败就会丢掉用户和存档。
                await PullFileAsync(Path.Combine(saveRoot, "users.dat"), USERS_KEY, true);

                // 设置、语言包启用列表同样要还原（它们不在 userdata 目录下）
                var dataRoot = Application.persistentDataPath;
                await PullFileAsync(Path.Combine(dataRoot, OPTIONS_FILE), OPTIONS_KEY, true);
                await PullFileAsync(Path.Combine(dataRoot, PACKS_FILE), PACKS_KEY, true);
                await PullFileAsync(Path.Combine(dataRoot, LANGPACKS_FILE), LANGPACKS_KEY, true);

                // privateKV 没有「列出所有 key」的接口，所以按 userIndex 递增探测：
                // 某个用户的全部 mod 存档都不存在时，认为后面没有更多用户，停止。
                for (int user = 0; user < MAX_PROBE_USERS; user++)
                {
                    // 注意：存档目录名是 user{index}（SaveManager.GetUserSaveDataDirectory），
                    // 不是纯数字。key 必须和 PathToKey 推送时生成的完全一致，否则拉不回来。
                    var userDir = $"user{user}";
                    bool anyExists = false;
                    foreach (var ns in modNamespaces)
                    {
                        var path = Path.Combine(saveRoot, userDir, ns, "user.dat");
                        var key = $"{KEY_PREFIX}u{userDir}_{ToKeyPart(ns)}";
                        var result = await PullFileAsync(path, key, true);
                        if (result != PullResult.Missing)
                            anyExists = true;

                        // 关卡进行中存档（单档）：先拿文件名，再还原到对应文件
                        var levelKey = $"{LEVEL_PREFIX}{userDir}_{ToKeyPart(ns)}";
                        var nameBytes = await KvGetAsync($"{LEVEL_NAME_PREFIX}{userDir}_{ToKeyPart(ns)}");
                        if (nameBytes != null && nameBytes.Length > 0)
                        {
                            var levelName = System.Text.Encoding.UTF8.GetString(nameBytes).Trim();
                            if (levelName.EndsWith(".lvl", StringComparison.OrdinalIgnoreCase) && levelName.IndexOfAny(new[] { '/', '\\', ':' }) < 0)
                            {
                                var levelPath = Path.Combine(saveRoot, userDir, ns, "level", levelName);
                                var levelResult = await PullFileAsync(levelPath, levelKey, true);
                                if (levelResult == PullResult.Restored)
                                {
                                    // 只保留这一份关卡存档
                                    RemoveOtherLevelStates(levelPath);
                                    anyExists = true;
                                }
                            }
                        }
                    }
                    if (!anyExists)
                        break;
                }
            }
        }
        #endregion

        #region 保存后上传
        /// <summary>本地存档写入成功后调用（不等待结果）。</summary>
        public static void QueuePush(string localPath, string saveRoot)
        {
            QueuePush(localPath);
        }
        /// <summary>同上，路径按 persistentDataPath 自动映射到云端 key。</summary>
        public static void QueuePush(string localPath)
        {
            if (!Supported || string.IsNullOrEmpty(localPath))
                return;
            _ = PushAsync(localPath, string.Empty);
        }
        private static async Task PushAsync(string localPath, string saveRoot)
        {
            try
            {
                var key = PathToKey(localPath, saveRoot);
                if (key == null)
                    return;
                if (!File.Exists(localPath))
                    return;
                var bytes = File.ReadAllBytes(localPath);
                // .lvl 是单档覆盖的关卡存档，还原时需要知道文件名
                if (localPath.EndsWith(".lvl", StringComparison.OrdinalIgnoreCase))
                {
                    var nameKey = LevelNameKeyFor(localPath);
                    if (nameKey != null)
                        await KvSetAsync(nameKey, System.Text.Encoding.UTF8.GetBytes(Path.GetFileName(localPath)));
                }
                // 空文件 / 极小文件一律不上传，避免把损坏的存档推到云端覆盖好数据
                if (bytes.Length < 8)
                {
                    Debug.LogWarning($"[CloudSave] {key} 内容异常（{bytes.Length} 字节），跳过上传");
                    return;
                }
                await PushFileAsync(localPath, key, bytes);
            }
            catch (Exception e)
            {
                Debug.LogWarning($"[CloudSave] 上传存档失败（忽略）：{e}");
            }
        }
        #endregion

        #region 单文件上传 / 下载
        private static async Task PushFileAsync(string localPath, string key, byte[] data)
        {
            var chunkCount = (data.Length + CHUNK_SIZE - 1) / CHUNK_SIZE;
            if (chunkCount < 1)
                chunkCount = 1;
            if (chunkCount > MAX_CHUNKS)
            {
                Debug.LogWarning($"[CloudSave] {localPath} 体积过大（{data.Length} 字节，需要 {chunkCount} 块 > 上限 {MAX_CHUNKS}），跳过云端同步");
                return;
            }

            var mtime = new DateTimeOffset(File.GetLastWriteTimeUtc(localPath)).ToUnixTimeSeconds();
            var entries = new Dictionary<string, byte[]>(chunkCount);
            for (int i = 0; i < chunkCount; i++)
            {
                var offset = i * CHUNK_SIZE;
                var len = Math.Min(CHUNK_SIZE, data.Length - offset);
                if (i == 0)
                {
                    // chunk 0 带头部
                    var header = new byte[1 + 4 + 8 + 8 + len];
                    header[0] = FORMAT_VERSION;
                    BitConverter.GetBytes(chunkCount).CopyTo(header, 1);
                    BitConverter.GetBytes((long)data.Length).CopyTo(header, 5);
                    BitConverter.GetBytes(mtime).CopyTo(header, 13);
                    Buffer.BlockCopy(data, offset, header, 21, len);
                    entries[$"{key}:0"] = header;
                }
                else
                {
                    var body = new byte[len];
                    Buffer.BlockCopy(data, offset, body, 0, len);
                    entries[$"{key}:{i}"] = body;
                }
            }

            // 逐块上传（分块数不多，避免依赖 KvSetMany 的批量语义）。
            foreach (var e in entries)
            {
                await KvSetAsync(e.Key, e.Value);
            }

            // 记录一下（下次换设备时能用上日志排查）
            Debug.Log($"[CloudSave] 已上传 {key}（{data.Length} 字节，{chunkCount} 块）");
        }

        /// <summary>把云端 key 对应的文件拉到本地。remoteNewerOnly=true 时只在云端更新才覆盖本地。</summary>
        private static async Task<PullResult> PullFileAsync(string localPath, string key, bool remoteNewerOnly)
        {
            var head = await KvGetAsync($"{key}:0");
            if (head == null || head.Length < 21 || head[0] != FORMAT_VERSION)
                return PullResult.Missing;

            var chunkCount = BitConverter.ToInt32(head, 1);
            var totalLen = BitConverter.ToInt64(head, 5);
            var remoteTime = BitConverter.ToInt64(head, 13);
            if (chunkCount <= 0 || chunkCount > MAX_CHUNKS || totalLen <= 0 || totalLen > (long)MAX_CHUNKS * CHUNK_SIZE)
            {
                Debug.LogWarning($"[CloudSave] {key} 头部异常（块数 {chunkCount}，长度 {totalLen}），跳过");
                return PullResult.Skipped;
            }

            if (remoteNewerOnly && File.Exists(localPath))
            {
                var localTime = new DateTimeOffset(File.GetLastWriteTimeUtc(localPath)).ToUnixTimeSeconds();
                if (localTime >= remoteTime)
                {
                    Debug.Log($"[CloudSave] 保持本地 {Path.GetFileName(localPath)}（本地 {localTime} >= 云端 {remoteTime}）");
                    return PullResult.Skipped; // 本地不旧，保持本地
                }
                Debug.Log($"[CloudSave] 云端较新，准备覆盖 {Path.GetFileName(localPath)}（本地 {localTime} < 云端 {remoteTime}）");
            }

            var data = new byte[totalLen];
            var headLen = head.Length - 21;
            Buffer.BlockCopy(head, 21, data, 0, headLen);
            var written = headLen;

            if (chunkCount > 1)
            {
                for (int i = 1; i < chunkCount; i++)
                {
                    var chunk = await KvGetAsync($"{key}:{i}");
                    if (chunk == null)
                    {
                        Debug.LogWarning($"[CloudSave] {key} 缺少第 {i} 块，放弃本次还原");
                        return PullResult.Skipped;
                    }
                    Buffer.BlockCopy(chunk, 0, data, written, chunk.Length);
                    written += chunk.Length;
                }
            }

            if (aborted)
                return PullResult.Skipped;
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(localPath) ?? ".");
                var temp = localPath + ".cloudtmp";
                File.WriteAllBytes(temp, data);
                if (File.Exists(localPath))
                    File.Delete(localPath);
                File.Move(temp, localPath);
                // 用云端记录的 mtime，避免下次比较时本地又变成「更新」
                File.SetLastWriteTimeUtc(localPath, DateTimeOffset.FromUnixTimeSeconds(remoteTime).UtcDateTime);
                pulledPaths.Add(localPath);
                Debug.Log($"[CloudSave] 已还原 {localPath}（{data.Length} 字节）");
                return PullResult.Restored;
            }
            catch (Exception e)
            {
                Debug.LogWarning($"[CloudSave] 写入本地文件失败 {localPath}：{e}");
                return PullResult.Skipped;
            }
        }
        #endregion

        /// <summary>还原后确保 level 目录里只留当前这一份 .lvl。</summary>
        private static void RemoveOtherLevelStates(string keepPath)
        {
            try
            {
                var dir = Path.GetDirectoryName(keepPath);
                if (string.IsNullOrEmpty(dir) || !Directory.Exists(dir))
                    return;
                var keepName = Path.GetFileName(keepPath);
                foreach (var file in Directory.GetFiles(dir, "*.lvl"))
                {
                    if (string.Equals(Path.GetFileName(file), keepName, StringComparison.Ordinal))
                        continue;
                    File.Delete(file);
                }
            }
            catch (Exception e)
            {
                Debug.LogWarning($"[CloudSave] 清理旧关卡存档失败（忽略）：{e}");
            }
        }
        #region SDK 调用封装
        /// <summary>读取一个 key。data 为 null 表示不存在（空字节是合法值）。</summary>
        private static Task<byte[]?> KvGetAsync(string key)
        {
            var tcs = new TaskCompletionSource<byte[]?>();
            try
            {
                BuildaSDK.KvGet(key, r =>
                {
                    if (!r.Ok)
                    {
                        Debug.LogWarning($"[CloudSave] KvGet({key}) 失败：{r.Error?.Code} {r.Error?.Message}");
                        tcs.TrySetResult(null);
                        return;
                    }
                    try
                    {
                        // privateKV.get 的 data 直接就是 base64 字符串，缺失时为 null。
                        var bytes = BuildaSDK.KvBytes(r.Data);
                        if (bytes == null && r.DataMap != null && r.DataMap.TryGetValue("data", out var inner))
                            bytes = BuildaSDK.KvBytes(inner);
                        tcs.TrySetResult(bytes);
                    }
                    catch (Exception e)
                    {
                        tcs.TrySetException(e);
                    }
                });
            }
            catch (Exception e)
            {
                tcs.TrySetException(e);
            }
            return tcs.Task;
        }
        private static Task KvSetAsync(string key, byte[] data)
        {
            var tcs = new TaskCompletionSource<bool>();
            try
            {
                BuildaSDK.KvSet(key, data, r =>
                {
                    if (!r.Ok)
                        Debug.LogWarning($"[CloudSave] KvSet({key}) 失败：{r.Error?.Code} {r.Error?.Message}");
                    tcs.TrySetResult(r.Ok);
                });
            }
            catch (Exception e)
            {
                tcs.TrySetException(e);
            }
            return tcs.Task;
        }
        #endregion

        #region 路径 / 工具
        private static string? PathToKey(string localPath, string saveRoot)
        {
            var root = Application.persistentDataPath.Replace('\\', '/').TrimEnd('/') + "/";
            var full = localPath.Replace('\\', '/');
            if (!full.StartsWith(root, StringComparison.Ordinal))
                return null;
            var rel = full.Substring(root.Length);
            if (rel.Contains(".bak") || rel.Contains(".cloudtmp"))
                return null; // 备份/临时文件不同步

            // 设置类文件
            if (rel == OPTIONS_FILE)
                return OPTIONS_KEY;
            if (rel == PACKS_FILE)
                return PACKS_KEY;
            if (rel == LANGPACKS_FILE)
                return LANGPACKS_KEY;

            // userdata/users.dat
            if (rel == "userdata/users.dat")
                return USERS_KEY;

            // userdata/{userIndex}/{modNamespace}/user.dat
            var parts = rel.Split('/');
            if (parts.Length == 4 && parts[0] == "userdata" && parts[3] == "user.dat")
                return $"{KEY_PREFIX}u{parts[1]}_{ToKeyPart(parts[2])}";
            // userdata/{userIndex}/{modNamespace}/level/{stage}.lvl —— 单档覆盖，用固定 key
            if (parts.Length == 5 && parts[0] == "userdata" && parts[3] == "level" && parts[4].EndsWith(".lvl", StringComparison.OrdinalIgnoreCase))
                return $"{LEVEL_PREFIX}{parts[1]}_{ToKeyPart(parts[2])}";
            return null;
        }
        /// <summary>userdata/{u}/{mod}/level/x.lvl -> mvz2_lvlname_{u}_{mod}</summary>
        private static string? LevelNameKeyFor(string localPath)
        {
            var root = Application.persistentDataPath.Replace('\\', '/').TrimEnd('/') + "/";
            var full = localPath.Replace('\\', '/');
            if (!full.StartsWith(root, StringComparison.Ordinal))
                return null;
            var parts = full.Substring(root.Length).Split('/');
            if (parts.Length == 5 && parts[0] == "userdata" && parts[3] == "level")
                return $"{LEVEL_NAME_PREFIX}{parts[1]}_{ToKeyPart(parts[2])}";
            return null;
        }
        private static string ToKeyPart(string raw)
        {
            var sb = new StringBuilder(raw.Length);
            foreach (var c in raw)
            {
                if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')
                    sb.Append(c);
                else if (c >= 'A' && c <= 'Z')
                    sb.Append(char.ToLowerInvariant(c));
                else
                    sb.Append('_');
            }
            return sb.ToString();
        }
        #endregion
    }

    /// <summary>
    /// WebGL（单线程、无可用定时器）下的帧级超时工具：
    /// 用 PlayerLoop 的 Update 计数，到期后回调一次。
    /// </summary>
    internal static class FrameTimeout
    {
        private static Ticker? ticker;
        private static readonly List<(long deadline, Action callback)> pending = new List<(long, Action)>();

        public static Task AfterFrames(int frames)
        {
            var tcs = new TaskCompletionSource<bool>();
            EnsureTicker();
            pending.Add((ticker!.Frame + frames, () => tcs.TrySetResult(true)));
            return tcs.Task;
        }
        private static void EnsureTicker()
        {
            if (ticker != null)
                return;
            var go = new GameObject("[CloudSaveFrameTicker]");
            UnityEngine.Object.DontDestroyOnLoad(go);
            go.hideFlags = HideFlags.HideAndDontSave;
            ticker = go.AddComponent<Ticker>();
        }
        private class Ticker : MonoBehaviour
        {
            public long Frame { get; private set; }
            private void Update()
            {
                Frame++;
                for (int i = pending.Count - 1; i >= 0; i--)
                {
                    if (Frame < pending[i].deadline)
                        continue;
                    var cb = pending[i].callback;
                    pending.RemoveAt(i);
                    try { cb(); } catch { }
                }
            }
        }
    }
}
